function applyLayoutMode(){document.body.classList.remove('layout-iphone','layout-ipad','layout-computer');if(layoutMode!=='auto')document.body.classList.add('layout-'+layoutMode);document.body.classList.toggle('computer-playing',(view==='game'&&!!state.match)||view==='arena-live');$$('[data-layout]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.layout===layoutMode)))}
