function toast(message,persistent=false){clearTimeout(toastTimeout);$('#toast').textContent=message;$('#toast').style.display='block';if(!persistent)toastTimeout=setTimeout(()=>$('#toast').style.display='none',4500)}
function currentRating(){return state.ratings.at(-1)?.value??state.profile?.currentRating??null}
