function stopArena(){arenaToken++;arenaWorker?.terminate();arenaWorker=null;clearTimeout(arenaTimer);arenaTimer=null}
function startArena(){const control=$('#arena-control').value,t=CONTROLS[control];arenaMatch={whiteLevel:Number($('#arena-white').value),blackLevel:Number($('#arena-black').value),control,increment:t.increment,clock:t.seconds?{w:t.seconds,b:t.seconds}:null,seed:Math.floor(Math.random()*0x100000000),moves:[],turn:'w',runningSince:Date.now(),paused:false,result:null,winner:null};view='arena-live';render();requestArenaMove()}
function tickArena(now=Date.now()){const m=arenaMatch;if(!m||!m.clock||m.paused||m.result)return false;const side=m.turn;m.clock[side]=Math.max(0,m.clock[side]-(now-m.runningSince)/1000);m.runningSince=now;if(m.clock[side]===0){m.result='timeout';m.winner=side==='w'?'b':'w';stopArena();return true}return false}
function requestArenaMove(){const m=arenaMatch;if(!m||m.paused||m.result||arenaWorker)return;const c=arenaPosition(),side=c.turn(),level=side==='w'?m.whiteLevel:m.blackLevel,remaining=m.clock?m.clock[side]:Infinity,config=LEVELS[level],budget=Math.max(50,Math.floor(Math.min(config.budget,remaining*1000/120))),id=++arenaToken,start=Date.now();arenaWorker=new Worker('opponent.js?v=20261113-14',{type:'module'});arenaWorker.onmessage=({data})=>{if(data.id!==arenaToken||arenaMatch!==m)return;arenaWorker?.terminate();arenaWorker=null;if(data.error||!data.move){m.result='error';stopArena();render();return}const wait=Math.min(140,Math.max(0,remaining*1000-(Date.now()-start)-50));arenaTimer=setTimeout(()=>{if(arenaMatch!==m||m.paused||m.result)return;if(tickArena())return render();try{const position=arenaPosition(),played=position.move(data.move);if(!played)throw Error();m.moves.push(played.san);if(m.clock)m.clock[side]+=m.increment;m.turn=position.turn();m.runningSince=Date.now();if(position.isGameOver()){m.result='finished';m.winner=position.isCheckmate()?side:null;m.reason=position.isCheckmate()?'Checkmate':position.isStalemate()?'Stalemate':position.isThreefoldRepetition()?'Threefold repetition':position.isInsufficientMaterial()?'Insufficient material':'Draw';stopArena()}render();if(!m.result)requestArenaMove()}catch{m.result='error';stopArena();render()}},wait)};arenaWorker.onerror=()=>{if(id!==arenaToken)return;arenaWorker?.terminate();arenaWorker=null;m.result='error';stopArena();render()};arenaWorker.postMessage({id,fen:c.fen(),level,budget,thinkMs:budget,history:m.moves,arena:true,variety:true,seed:m.seed})}
function bindArena(){if($('#start-arena'))$('#start-arena').onclick=startArena;if($('#arena-control'))$('#arena-control').onchange=()=>{$$('#arena-white,#arena-black').forEach(select=>refreshBotSelect(select,$('#arena-control').value))};if($('#time-control'))$('#time-control').onchange=()=>refreshBotSelect($('#game-level'),$('#time-control').value);if($('#start-game'))$('#start-game').onclick=()=>startMatch();if($('#arena-exit'))$('#arena-exit').onclick=()=>{stopArena();arenaMatch=null;go('arena')};if($('#arena-new'))$('#arena-new').onclick=()=>{stopArena();arenaMatch=null;go('arena')};if($('#arena-result-new'))$('#arena-result-new').onclick=()=>{stopArena();arenaMatch=null;go('arena')};if($('#arena-pause'))$('#arena-pause').onclick=()=>{const m=arenaMatch;if(!m)return;if(m.paused){m.paused=false;m.runningSince=Date.now();render();requestArenaMove()}else{tickArena();if(m.result)return render();m.paused=true;stopArena();render()}};if(view==='arena-live'&&arenaMatch){const moves=$('.live-moves-scroll');if(moves)moves.scrollTop=moves.scrollHeight}}
function startMatch(exercise=null){stopEngine();const control=exercise?'0':$('#time-control').value,t=CONTROLS[control];const chosen=exercise?2:Number($('#game-level').value),level=chosen===6&&!['30s','1'].includes(control)?5:chosen;state.match={id:Date.now(),moves:[],level,control,increment:t.increment,clock:t.seconds?{w:t.seconds,b:t.seconds}:null,turn:'w',runningSince:Date.now(),paused:false,kind:exercise?'endgame':'game',seed:Math.floor(Math.random()*0x100000000),...(exercise?{fen:exercise.fen,exercise:exercise.id}:{})};gameSelection=null;save();go('game')}
function requestReply(){const m=state.match;if(thinking||!m||m.paused||m.result||m.error)return;const c=match();if(c.turn()!=='b'||c.isGameOver())return;thinking=true;const id=++job,start=Date.now(),timing=botTiming(m.level,m.clock,m.increment);engine=new Worker('opponent.js?v=20261113-14',{type:'module'});engine.onmessage=({data})=>{if(data.id!==job||state.match!==m)return;engine?.terminate();engine=null;if(data.error||!data.move){thinking=false;m.error=true;save();if(view==='game')render();return}const remaining=m.clock?Math.max(0,m.clock.b*1000-(Date.now()-m.runningSince)-150):Infinity;const wait=Math.min(Math.max(0,timing.delay-(Date.now()-start)),remaining);replyTimer=setTimeout(()=>{if(id!==job||state.match!==m||m.paused)return;thinking=false;if(settleMatch())return render();try{commitMove(m,data.move);if(m.premove&&!m.result){if(!executePremove(m))toast('Premove cancelled because the computer’s move made it illegal.')}if(m.result)recordGame();save()}catch{m.error=true;save()}if(view==='game')render()},wait)};engine.onerror=(e)=>{thinking=false;m.error=true;toast(e.message||'Computer could not load. Please retry.');engine?.terminate();engine=null;save();if(view==='game')render()};engine.postMessage({id,fen:c.fen(),level:m.level,initialFen:m.fen,history:c.history({verbose:true}).map(x=>x.san),variety:m.kind==='game',seed:m.seed,thinkMs:timing.budget,budget:timing.budget})}
function toggleGamePause(){if(!state.match||settleMatch()||state.match.result)return render();delete state.match.premove;state.match.paused=!state.match.paused;state.match.runningSince=Date.now();stopEngine();gameSelection=null;save();render()}
function playGameMove(move){const m=state.match;if(!m||m.result||m.paused||thinking||settleMatch())return render();try{commitMove(m,move);gameSelection=null;if(m.result)recordGame();save();requestReply();render()}catch{toast('That move is not legal. Keep your king safe.')}}
function resignGame(){const m=state.match;if(!m||m.result)return;settleMatch();if(m.result)return render();stopEngine();m.result='loss';m.reason='You resigned';m.paused=false;gameSelection=null;recordGame();save();render()}
function handleGameSquare(sq){const m=state.match;if(!m||m.paused||m.result||settleMatch())return;const c=match();if(c.turn()==='b'){if(c.get(sq)?.color==='w'){gameSelection=sq;render();return}if(gameSelection){const from=gameSelection;m.premove={from,to:sq,promotion:'q'};gameSelection=null;save();render()}return}if(c.get(sq)?.color==='w'){gameSelection=sq;render();return}if(!gameSelection)return;const from=gameSelection,candidates=c.moves({square:from,verbose:true}).filter(move=>move.to===sq);if(!candidates.length)return toast('That move is not legal. Choose a highlighted square.');if(candidates.some(move=>move.promotion)){const modal=$('#promotion');$('#promotion .promotion-options').innerHTML=['q','r','b','n'].map(piece=>`<button data-game-promote="${piece}"><img width="48" height="48" src="pieces/w${piece.toUpperCase()}.svg" alt="${names[piece]}">${names[piece]}</button>`).join('');$$('[data-game-promote]').forEach(button=>button.onclick=()=>{modal.close();playGameMove({from,to:sq,promotion:button.dataset.gamePromote})});modal.showModal();return}playGameMove({from,to:sq})}
function bindGameBoard(){let dragFrom=null;$$('[data-square]').forEach(button=>button.onclick=()=>{if(Date.now()<ignoreGameClickUntil)return;handleGameSquare(button.dataset.square)});const surface=$('.game-room .game-board');if(!surface)return;surface.addEventListener('pointerdown',event=>{const square=event.target.closest?.('[data-square]');if(event.pointerType==='touch'||event.button!==0||!square||!state.match||state.match.paused||state.match.result)return;const c=match();if(c.get(square.dataset.square)?.color==='w')dragFrom=square.dataset.square});surface.addEventListener('pointerup',event=>{const from=dragFrom;dragFrom=null;if(!from)return;const to=event.target.closest?.('[data-square]')?.dataset.square;if(!to||to===from)return;ignoreGameClickUntil=Date.now()+700;handleGameSquare(from);handleGameSquare(to)});surface.addEventListener('pointercancel',()=>{dragFrom=null});surface.addEventListener('contextmenu',event=>{event.preventDefault();if(!state.match)return;gameSelection=null;delete state.match.premove;save();render()})}
function bindGame(){bindReview();if($('#cancel-premove'))$('#cancel-premove').onclick=()=>{delete state.match.premove;gameSelection=null;save();render()};$$('[data-endgame]').forEach(b=>b.onclick=()=>{if(state.match&&!state.match.result)return toast('Finish or save your current game first.');startMatch(ENDGAMES.find(e=>e.id===b.dataset.endgame))});if(view!=='game')return;if($('#resign-game'))$('#resign-game').onclick=resignGame;if($('#start-game'))$('#start-game').onclick=()=>startMatch();if($('#pause-game'))$('#pause-game').onclick=toggleGamePause;if($('#resume-game'))$('#resume-game').onclick=toggleGamePause;if($('#retry-computer'))$('#retry-computer').onclick=()=>{state.match.error=false;requestReply();render()};if($('#save-end-game'))$('#save-end-game').onclick=()=>{settleMatch();if(!state.match.recorded)recordGame(match(),true);stopEngine();state.match=null;save();reviewGameIndex=state.games.length-1;gameStep=0;go('games')};if($('#new-game'))$('#new-game').onclick=()=>{const end=state.match.kind==='endgame';stopEngine();state.match=null;save();go(end?'endgames':'game')};if(state.match){bindGameBoard();const moveScroll=$('.live-moves-scroll');if(moveScroll)moveScroll.scrollTop=moveScroll.scrollHeight;requestReply()}}
function endgamesPage(){const done=state.endgamesDone||[];return `<div class="simple-home"><div class="eyebrow">SMALL BOARDS, BIG IMPROVEMENT</div><h1>Finish the game.</h1><p>Play these positions against the computer. White moves first. Win by checkmate; draws explain what happened.</p>${state.match&&!state.match.result?'<div class="coach-note"><p>You have a game in progress.</p><button class="button primary" data-goto="game">Continue game</button></div>':''}${ENDGAMES.map((e,i)=>`<div class="panel section-space"><div class="row wrap"><h2>${i+1}. ${e.name}</h2><span class="badge">${done.includes(e.id)?'Completed':'Ready to practice'}</span></div><p>${e.tip}</p><button class="button ${done.includes(e.id)?'secondary':'primary'}" data-endgame="${e.id}" ${state.match&&!state.match.result?'disabled':''}>${done.includes(e.id)?'Practice again':'Practice this endgame'}</button></div>`).join('')}<p class="fine section-space">Untimed practice. Completed positions repeat only when you choose Practice again.</p></div>`}
function gamesPage(){
  const games=state.games||[];
  if(reviewGameIndex==null||!games[reviewGameIndex])return `<div class="simple-home"><div class="eyebrow">LEARN FROM YOUR OWN MOVES</div><h1>Game review.</h1><p>Replay a game and follow the evaluation bar as the position changes.</p>${games.length?games.map((g,i)=>`<div class="panel section-space row wrap"><div><b>${g.kind==='endgame'?'Endgame':'Computer game'} · ${esc(g.date)}</b><p class="fine">${g.result==='ended'?'Unfinished':g.result} · ${g.moves.length} half-moves · ${LEVELS[g.level]?.name||'Little Fish'} · ${CONTROLS[g.control]?.name||'Untimed'}</p></div><button class="button secondary" data-open-game="${i}">Review game ${i+1}</button></div>`).reverse().join(''):'<div class="panel"><p>Your games will appear here automatically.</p><button class="button primary" data-goto="game">Play your first game</button></div>'}</div>`;
  const g=games[reviewGameIndex],summary=gameSummary(g);
  gameStep=clamp(gameStep,0,g.moves.length);
  const c=gameFrom(g,gameStep),r=summary.rows[gameStep-1],analysis=g.analysis?.[gameStep-1];
  let previousIndex=-1;
  for(let i=gameStep-2;i>=0;i--)if(['search','stockfish'].includes(g.analysis?.[i]?.engine)){previousIndex=i;break}
  const previousAnalysis=previousIndex>=0?g.analysis[previousIndex]:null;
  const previousColor=previousIndex>=0?summary.rows[previousIndex].color:'w';
  const shownAnalysis=analysis||previousAnalysis;
  const shownColor=analysis?r?.color:previousColor;
  const ev=gameStep===0?evaluation({engine:'search',actualScore:0,actualMate:null},'w'):evaluation(shownAnalysis,shownColor);
  return `<div class="review-room"><div class="row wrap"><button class="button secondary" id="all-games">All games</button><h2>Move ${gameStep} of ${g.moves.length}</h2><button class="button primary" id="complete-review">Mark reviewed</button></div><div class="review-layout simple-review"><div><div class="review-board-with-eval"><div class="eval-column" role="img" aria-label="${esc(ev.description)}: ${ev.text}"><span class="eval-number">${ev.text}</span><div class="eval-track"><div class="eval-white" style="height:${ev.white}%"></div></div><small>White</small></div><div class="game-board">${boardHTML(c,{staticBoard:true,last:r})}</div></div><div class="row wrap section-space"><button class="button secondary" id="game-prev" ${gameStep===0?'disabled':''}>Previous move</button><button class="button primary" id="game-next" ${gameStep===g.moves.length?'disabled':''}>Next move</button></div></div></div></div>`
}
function cancelReviewAnalysis(){analysisToken++;analysisWorker?.terminate();analysisWorker=null;analysisBusy=false;analysisStep=0}
function startReviewAnalysis(gameIndex,step,chain=true){
  const g=state.games?.[gameIndex],rows=g?moveNotes(g):[],row=rows[step-1];
  if(!g||!row||analysisBusy)return;
  const key=gameIndex+':'+step;
  reviewAttempts.add(key);analysisBusy=true;analysisStep=step;
  const id=++analysisToken;
  analysisWorker=new Worker('opponent.js?v=20261113-14',{type:'module'});
  analysisWorker.onmessage=({data})=>{
    if(data.id!==analysisToken)return;
    analysisBusy=false;analysisWorker.terminate();analysisWorker=null;
    if(data.error)toast('Analysis could not finish. Try again.');
    else{g.analysis||=[];g.analysis[step-1]={...data,engine:'search',analyzedAt:Date.now()};save()}
    if(view==='games'&&reviewGameIndex===gameIndex)render();
    if(chain)queueReviewAnalysis(gameIndex);
  };
  analysisWorker.onerror=()=>{
    if(id!==analysisToken)return;
    analysisBusy=false;analysisWorker?.terminate();analysisWorker=null;
    toast('Analysis could not load. Try again.');
    if(view==='games'&&reviewGameIndex===gameIndex)render();
    if(chain)queueReviewAnalysis(gameIndex);
  };
  const moving=gameFrom(g,step).history({verbose:true}).at(-1);
  analysisWorker.postMessage({id,fen:row.before,review:true,chosenSan:moving.san,chosenUci:moving.from+moving.to+(moving.promotion||''),level:4,budget:800});
  if(view==='games'&&reviewGameIndex===gameIndex)render();
}
function queueReviewAnalysis(gameIndex){
  if(analysisBusy)return;
  const g=state.games?.[gameIndex];if(!g)return;
  for(let step=1;step<=g.moves.length;step++){
    const cached=g.analysis?.[step-1],key=gameIndex+':'+step;
    if(!['search','stockfish'].includes(cached?.engine)&&!reviewAttempts.has(key)){
      startReviewAnalysis(gameIndex,step,true);return;
    }
  }
}
function bindReview(){
  $$('[data-open-game]').forEach(b=>b.onclick=()=>{cancelReviewAnalysis();reviewGameIndex=Number(b.dataset.openGame);gameStep=0;go('games')});
  if($('#all-games'))$('#all-games').onclick=()=>{cancelReviewAnalysis();reviewGameIndex=null;render()};
  if($('#game-prev'))$('#game-prev').onclick=()=>{gameStep--;render()};
  if($('#game-next'))$('#game-next').onclick=()=>{gameStep++;render()};
  if($('#game-jump'))$('#game-jump').onchange=e=>{gameStep=Number(e.target.value);render()};
  if($('#complete-review'))$('#complete-review').onclick=()=>{state.checks[weekKey()]||={};state.checks[weekKey()].review=true;state.games[reviewGameIndex].reviewed=true;save();cancelReviewAnalysis();go('dashboard');toast('Game reviewed. Take one lesson into your next game.')};
  if($('#analyze-move'))$('#analyze-move').onclick=()=>{if(analysisBusy)return;startReviewAnalysis(reviewGameIndex,gameStep,false)};
  if(view==='games'&&reviewGameIndex!=null)queueReviewAnalysis(reviewGameIndex);
}
function trainingCoach(){if(!state.trainingCoach){const coaches=Object.values(state.coach||newCoach(currentRating()));state.trainingCoach={...coaches[0],target:Math.round(coaches.reduce((n,c)=>n+c.target,0)/coaches.length),fast:0,struggles:0,total:0,solved:0};state.trainingBaseline=state.trainingCoach.target}return state.trainingCoach}
function adjustChallenge(delta){const c=trainingCoach();const previous=state.active?.puzzle?puzzleMap.get(state.active.puzzle.id)?.rating:null;c.target=clamp((delta>0?Math.max(c.target,previous||0):Math.min(c.target,previous||c.target))+delta,400,2500);c.fast=0;c.struggles=0;c.reason='You adjusted the challenge. Automatic adjustment is still on.';state.challengeDirection=delta>0?'up':'down';if(state.active?.puzzle&&!state.active.puzzle.done&&!state.active.puzzle.moves.length&&!state.active.puzzle.mistakes.length&&!state.active.puzzle.hints){newPuzzle();}save();render();toast('Next fresh puzzle targets '+c.target+'. Automatic adjustment stays on.')}
function chooseTrainingPuzzle(skill){const c=trainingCoach(),fresh=bank.filter(p=>p.skill===skill&&!state.seen.includes(p.id)&&!state.seenPositions.includes(positionKey(p.fen)));const directed=state.challengeDirection==='up'?fresh.filter(p=>p.rating>=c.target):state.challengeDirection==='down'?fresh.filter(p=>p.rating<=c.target):fresh;return pickPuzzle(directed.length?directed:fresh,skill,c.target,[],[])}
function improvementHTML(){const c=trainingCoach(),results=state.sessions.filter(s=>s.version===2).flatMap(s=>s.results).concat(state.active?.results||[]),last=results.slice(-10),previous=results.slice(-20,-10),rate=a=>a.length?Math.round(a.filter(r=>r.clean).length/a.length*100):0;const rating=currentRating(),start=state.profile?.startRating,goal=state.profile?.goal||1500;return `<div class="panel section-space"><div class="row wrap"><h2>Your progress</h2><span class="badge">Automatic difficulty on</span></div><p><b>Puzzle target ${fmt(c.target)}</b> · ${c.target-(state.trainingBaseline||c.target)>=0?'+':''}${c.target-(state.trainingBaseline||c.target)} since tracking began</p><p class="fine">${last.length?`${rate(last)}% clean solves in your last ${last.length} puzzle${last.length===1?'':'s'}${previous.length?` · ${rate(last)-rate(previous)>=0?'+':''}${rate(last)-rate(previous)} percentage points versus the previous ${previous.length}`:''}.`:'Solve a few puzzles to start your trend.'} ${esc(c.reason)}</p>${rating!=null?`<div class="progress-track"><span style="width:${progressPercent()}%"></span></div><p class="fine">Game rating ${fmt(rating)} → goal ${fmt(goal)} · ${Math.max(0,goal-rating)} points to go${start!=null?` · ${rating-start>=0?'+':''}${rating-start} from your starting rating`:''}.</p>`:`<p class="fine">Goal: ${fmt(goal)} game rating. Add a game rating when you have one.</p>`}<p class="fine muted">Puzzle progress and computer results do not automatically change your game rating.</p></div>`}
$$('nav button').forEach(b=>b.onclick=()=>go(b.dataset.view));$('#home-button').onclick=()=>go('dashboard');$('.brand').onclick=e=>{e.preventDefault();go('dashboard')};$('#export').onclick=exportData;$('#import').onchange=importData;$('#cancel-promotion').onclick=()=>{pendingPromotion=null;$('#promotion').close()};document.addEventListener('visibilitychange',()=>{flushTime();lastTick=Date.now()});window.addEventListener('beforeunload',()=>{settleMatch();flushTime();save()});setInterval(()=>{if(view==='game'&&state.match?.clock&&!state.match.result&&!state.match.paused){if(settleClock(state.match)){stopEngine();recordGame();save();render()}else{const w=$('#white-clock'),b=$('#black-clock');if(w)w.textContent=clockDisplay(state.match.clock.w);if(b)b.textContent=clockDisplay(state.match.clock.b)}}if(view==='arena-live'&&arenaMatch&&!arenaMatch.paused&&!arenaMatch.result){if(tickArena())render();else{const w=$('#arena-white-clock'),b=$('#arena-black-clock');if(w)w.textContent=arenaMatch.clock?clockDisplay(arenaMatch.clock.w):'Untimed';if(b)b.textContent=arenaMatch.clock?clockDisplay(arenaMatch.clock.b):'Untimed'}}},50);setInterval(()=>{if(state.match&&!state.match.result&&!state.match.paused){const ended=settleMatch();if(!ended)save();if(view==='game'){if(ended)render();else{if($('#white-clock'))$('#white-clock').textContent=state.match.clock?clockDisplay(state.match.clock.w):'Untimed';if($('#black-clock'))$('#black-clock').textContent=state.match.clock?clockDisplay(state.match.clock.b):'Untimed'}}}flushTime();if($('#session-time')&&state.active)$('#session-time').textContent=duration(state.active.seconds);if($('#puzzle-time')&&state.active?.puzzle)$('#puzzle-time').textContent=relativeTime(state.active.puzzle.seconds)},1000);
try{const [p,l]=await Promise.all([fetch('puzzles.json').then(r=>{if(!r.ok)throw Error();return r.json()}),fetch('legacy-lessons.json').then(r=>r.json())]);bank=p;legacy=l;puzzleMap=new Map(bank.map(p=>[p.id,p]));if(state.coach&&!state.extraChallenge){for(const c of Object.values(state.coach))c.target=Math.min(2500,c.target+150);state.extraChallenge=true;save();}if(state.profile&&!state.coach)state.coach=newCoach(currentRating());if(state.coach&&!state.challengeUplift){for(const c of Object.values(state.coach)){c.target=Math.min(2500,c.target+250);c.reason='A higher starting challenge, as requested. Your results will guide the next steps.'}state.challengeUplift=true;save();}trainingCoach();if(state.match){state.match.level=Number(state.match.level)||2;state.match.turn=match().turn();settleMatch();}if(state.active&&!puzzleMap.has(state.active.puzzle?.id))state.active=null;render()}catch{$('#content').innerHTML='<div class="panel empty"><h1>Your training room couldn’t load.</h1><p>Check your connection and reload. Your saved records are still in this browser.</p><button class="button primary" id="reload-app">Reload training room</button></div>';$('#reload-app').onclick=()=>location.reload();}

function syncBoard(oldBoard,newBoard){oldBoard.setAttribute('aria-label',newBoard.getAttribute('aria-label'));[...newBoard.children].forEach((fresh,i)=>{const old=oldBoard.children[i];for(const a of [...old.attributes])if(!fresh.hasAttribute(a.name))old.removeAttribute(a.name);for(const a of fresh.attributes)old.setAttribute(a.name,a.value);const oldImage=old.querySelector('img'),newImage=fresh.querySelector('img');if(oldImage&&newImage&&oldImage.getAttribute('src')===newImage.getAttribute('src')){for(const child of [...old.children])if(child!==oldImage)child.remove();for(const child of [...fresh.children])if(child!==newImage)old.append(child.cloneNode(true));}else old.innerHTML=fresh.innerHTML;});}
let dragGesture=null,suppressBoardClick=false;
document.addEventListener('pointerdown',e=>{const square=e.target.closest('.square[data-square]');if(!square||e.button!==0||!square.querySelector('img'))return;const game=view==='game'&&state.match?match():view==='training'&&state.active?activeGame():null;if(!game)return;const color=view==='game'?'w':new Chess(puzzleMap.get(state.active.puzzle.id).fen).turn();if(game.get(square.dataset.square)?.color!==color)return;dragGesture={from:square.dataset.square,x:e.clientX,y:e.clientY,board:square.closest('.board'),square,pointer:e.pointerId};square.setPointerCapture(e.pointerId);});
document.addEventListener('pointermove',e=>{const d=dragGesture;if(!d||d.pointer!==e.pointerId)return;if(!d.ghost&&Math.hypot(e.clientX-d.x,e.clientY-d.y)>6){d.ghost=d.square.querySelector('img').cloneNode();d.ghost.className='drag-piece';d.ghost.style.width=d.square.getBoundingClientRect().width+'px';document.body.append(d.ghost);d.square.classList.add('drag-origin')}if(d.ghost){e.preventDefault();d.ghost.style.left=e.clientX+'px';d.ghost.style.top=e.clientY+'px';}},{passive:false});
function clearDrag(){const d=dragGesture;dragGesture=null;if(d){d.ghost?.remove();d.square.classList.remove('drag-origin');if(d.square.hasPointerCapture(d.pointer))d.square.releasePointerCapture(d.pointer)}return d;}
document.addEventListener('pointerup',e=>{const d=clearDrag();if(!d?.ghost)return;suppressBoardClick=true;setTimeout(()=>suppressBoardClick=false,0);const destination=document.elementFromPoint(e.clientX,e.clientY)?.closest('.square[data-square]');if(!destination||destination.closest('.board')!==d.board||destination.dataset.square===d.from)return;if(view==='game')gameSelection=d.from;else selectedSquare=d.from;destination.onclick?.();});
document.addEventListener('pointercancel',clearDrag);document.addEventListener('click',e=>{if(suppressBoardClick&&e.target.closest('.board')){e.preventDefault();e.stopImmediatePropagation()}},true);
